```go
package main

import (
    "fmt"
    "sync"
)

func main() {
    results := make(chan int)
    var wg sync.WaitGroup
    for _, value := range []int{20, 22} {
        wg.Add(1)
        go func(n int) {
            defer wg.Done()
            results <- n
        }(value)
    }
    go func() {
        wg.Wait()
        close(results)
    }()

    total := 0
    for value := range results { total += value }
    fmt.Println(total)
}
```
The coordinator closes only after both sends finish. Arrival order may vary, but the output is always `42`.
